#!/usr/bin/env bash

set -euo pipefail

SCRIPT_NAME="$(basename "$0")"
DEFAULT_PROJECT_NAME="exile_updater"
DEFAULT_AUTHOR="yangyuexiong"
DEFAULT_TARGET="."
CURRENT_TIME="$(date '+%Y-%m-%d %H:%M:%S')"

usage() {
  cat <<EOF
Usage:
  $SCRIPT_NAME [options]

Options:
  -n, --name NAME       Project name. Supports letters, numbers, "_" and "-". Default: ${DEFAULT_PROJECT_NAME}
  -a, --author AUTHOR   Author name written into generated files. Default: ${DEFAULT_AUTHOR}
  -t, --target PATH     Target directory. Default: ${DEFAULT_TARGET}
      --force           Overwrite existing files generated by this script
      --dry-run         Print planned actions without writing files
  -h, --help            Show this help message

Examples:
  ./$SCRIPT_NAME
  ./$SCRIPT_NAME --author yangyuexiong
  ./$SCRIPT_NAME --name exile_updater --target /tmp/demo
  ./$SCRIPT_NAME --name exile-updater --target /tmp/demo
  ./$SCRIPT_NAME --dry-run
EOF
}

PROJECT_NAME="$DEFAULT_PROJECT_NAME"
PROJECT_IDENTIFIER="$DEFAULT_PROJECT_NAME"
AUTHOR="$DEFAULT_AUTHOR"
TARGET_DIR="$DEFAULT_TARGET"
FORCE=0
DRY_RUN=0

while [[ $# -gt 0 ]]; do
  case "$1" in
    -n|--name)
      [[ $# -ge 2 ]] || { echo "Missing value for $1" >&2; exit 1; }
      PROJECT_NAME="$2"
      shift 2
      ;;
    -a|--author)
      [[ $# -ge 2 ]] || { echo "Missing value for $1" >&2; exit 1; }
      AUTHOR="$2"
      shift 2
      ;;
    -t|--target)
      [[ $# -ge 2 ]] || { echo "Missing value for $1" >&2; exit 1; }
      TARGET_DIR="$2"
      shift 2
      ;;
    --force)
      FORCE=1
      shift
      ;;
    --dry-run)
      DRY_RUN=1
      shift
      ;;
    -h|--help)
      usage
      exit 0
      ;;
    *)
      echo "Unknown option: $1" >&2
      usage >&2
      exit 1
      ;;
  esac
done

if [[ ! "$PROJECT_NAME" =~ ^[A-Za-z][A-Za-z0-9_-]*$ ]]; then
  echo "Invalid project name: $PROJECT_NAME" >&2
  echo 'Use a valid project name, for example: exile_updater or operational-risk-updater' >&2
  exit 1
fi

if [[ -z "${AUTHOR// }" ]]; then
  echo "Invalid author: $AUTHOR" >&2
  echo 'Use a non-empty author name.' >&2
  exit 1
fi

PROJECT_IDENTIFIER="${PROJECT_NAME//-/_}"

TARGET_DIR="${TARGET_DIR%/}"
if [[ -z "$TARGET_DIR" ]]; then
  TARGET_DIR="."
fi

log() {
  printf '[init] %s\n' "$1"
}

run_mkdir() {
  local dir="$1"
  if [[ "$DRY_RUN" -eq 1 ]]; then
    log "mkdir -p $dir"
    return
  fi
  mkdir -p "$dir"
  log "created directory: $dir"
}

write_file() {
  local file="$1"
  local content="$2"

  if [[ -f "$file" && "$FORCE" -ne 1 ]]; then
    log "skip existing file: $file"
    return
  fi

  if [[ "$DRY_RUN" -eq 1 ]]; then
    if [[ -f "$file" ]]; then
      log "overwrite file: $file"
    else
      log "create file: $file"
    fi
    return
  fi

  printf '%s' "$content" > "$file"
  if [[ -f "$file" && "$FORCE" -eq 1 ]]; then
    log "wrote file: $file"
  else
    log "created file: $file"
  fi
}

run_mkdir "$TARGET_DIR"

APP_DIR="$TARGET_DIR/app"

DIRS=(
  "$APP_DIR"
  "$APP_DIR/api"
  "$APP_DIR/api/v1"
  "$APP_DIR/api/v1/endpoints"
  "$APP_DIR/core"
  "$APP_DIR/db"
  "$APP_DIR/models"
  "$APP_DIR/schemas"
  "$APP_DIR/services"
  "$APP_DIR/tasks"
  "$APP_DIR/utils"
  "$APP_DIR/static"
  "$TARGET_DIR/scripts"
  "$TARGET_DIR/tests"
)

for dir in "${DIRS[@]}"; do
  run_mkdir "$dir"
done

write_file "$APP_DIR/__init__.py" ""
write_file "$APP_DIR/api/__init__.py" ""
write_file "$APP_DIR/api/v1/__init__.py" ""
write_file "$APP_DIR/api/v1/endpoints/__init__.py" ""
write_file "$APP_DIR/core/__init__.py" ""
write_file "$APP_DIR/db/__init__.py" ""
write_file "$APP_DIR/models/__init__.py" "$(cat <<EOF
