write_file "$APP_DIR/core/exception_handlers.py" "$(cat <<EOF
# -*- coding: utf-8 -*-
# @Time    : ${CURRENT_TIME}
# @Author  : ${AUTHOR}
# @File    : exception_handlers.py

from typing import Any, Optional

from fastapi import FastAPI, HTTPException, Request
from fastapi.exceptions import RequestValidationError
from fastapi.responses import JSONResponse
from loguru import logger

from app.core.custom_exception import CustomException


def register_exception_handlers(app: FastAPI, debug: bool):
    def _get_request_id(request: Request) -> Optional[str]:
        return getattr(request.state, "request_id", None) or request.headers.get("x-request-id")

    def _build_response(
        *,
        code: int,
        message: str,
        http_status: int,
        data: Any = None,
        request_id: Optional[str] = None,
    ) -> JSONResponse:
        content = {
            "code": code,
            "message": message,
            "data": data,
        }
        if data is None:
            content.pop("data")
        if request_id:
            content["request_id"] = request_id
        return JSONResponse(status_code=http_status, content=content)

    @app.exception_handler(CustomException)
    async def custom_exception_handler(request: Request, exc: CustomException):
        request_id = _get_request_id(request)
        logger.bind(request_id=request_id).warning(f"CustomException: {exc.detail}")
        return _build_response(
            code=exc.custom_code,
            message=str(exc.detail),
            http_status=exc.status_code,
            data=exc.data,
            request_id=request_id,
        )

    @app.exception_handler(HTTPException)
    async def http_exception_handler(request: Request, exc: HTTPException):
        request_id = _get_request_id(request)
        logger.bind(request_id=request_id).info(f"HTTPException: {exc.detail}")
        return _build_response(
            code=exc.status_code,
            message=str(exc.detail),
            http_status=exc.status_code,
            request_id=request_id,
        )

    @app.exception_handler(Exception)
    async def base_exception_handler(request: Request, exc: Exception):
        request_id = _get_request_id(request)
        logger.bind(request_id=request_id).exception("Unhandled exception")
        data = [str(exc)] if debug else None
        return _build_response(
            code=500,
            message="Internal server error",
            http_status=500,
            data=data,
            request_id=request_id,
        )

    @app.exception_handler(RequestValidationError)
    async def validation_exception_handler(request: Request, exc: RequestValidationError):
        request_id = _get_request_id(request)
        error_messages = []
        if debug:
            for error in exc.errors():
                error_messages.append({
                    "type": "validation_error",
                    "msg": error.get("msg"),
                    "loc": list(error.get("loc")),
                    "input": error.get("type"),
                })
        return _build_response(
            code=400,
            message="缺少必要的参数，参数类型错误",
            http_status=400,
            data=error_messages if debug else None,
            request_id=request_id,
        )
EOF
)"

write_file "$APP_DIR/core/lifespan.py" "$(cat <<EOF
# -*- coding: utf-8 -*-
# @Time    : ${CURRENT_TIME}
# @Author  : ${AUTHOR}
# @File    : lifespan.py

import datetime
import os
import platform
import threading
from contextlib import asynccontextmanager, suppress

from apscheduler.schedulers.base import SchedulerNotRunningError
from fastapi import FastAPI
from loguru import logger

import app.db.redis_client as redis_module
from app.core.config import get_config
from app.db.redis_client import close_redis_connection_pool, create_redis_connection_pool
from app.db.session import close_db, init_db
from app.tasks.scheduler import scheduler, scheduler_init

project_config = get_config()


def _log_startup_info() -> None:
    fast_api_env = os.getenv("FAST_API_ENV", "development")
    logger.info(">>> startup")
    logger.info("<" + "-" * 66 + ">")
    logger.info(f"时间: {datetime.datetime.now()}")
    logger.info(f"操作系统: {platform.system()}")
    logger.info(f"项目路径: {os.getcwd()}")
    logger.info(f"当前环境: {fast_api_env} (config: {project_config.ENV})")
    logger.info(f"父进程id: {os.getppid()}")
    logger.info(f"子进程id: {os.getpid()}")
    logger.info(f"线程id: {threading.get_ident()}")
    logger.info("<" + "-" * 66 + ">")


async def _init_db() -> None:
    logger.info(">>> Mysql连接池初始化")
    await init_db()


async def _init_redis() -> None:
    logger.info(">>> Redis连接池初始化")
    await create_redis_connection_pool()
    logger.debug(f"redis_pool: {redis_module.redis_pool!r}")
    logger.info(">>> Redis 连接池初始化完成")


async def _init_scheduler() -> None:
    await scheduler_init()
    logger.info(">>> 定时任务初始化")


async def _shutdown_scheduler() -> None:
    if getattr(scheduler, "running", False):
        try:
            with suppress(SchedulerNotRunningError):
                scheduler.shutdown(wait=False)
            logger.info(">>> 定时任务已关闭")
        except Exception:
            logger.exception(">>> 定时任务关闭失败")
    else:
        logger.info(">>> 定时任务未启动，跳过关闭")


async def _shutdown_redis() -> None:
    try:
        await close_redis_connection_pool()
        logger.info(">>> Redis 连接池已关闭")
    except Exception:
        logger.exception(">>> Redis 连接池关闭失败")


async def _shutdown_db() -> None:
    try:
        await close_db()
        logger.info(">>> 数据库连接已关闭")
    except Exception:
        logger.exception(">>> 数据库连接关闭失败")


async def startup_event() -> None:
    _log_startup_info()
    logger.info(f">>> Config初始化: {project_config.ENV}")

    try:
        await _init_db()
        await _init_redis()
        # await _init_scheduler()
    except Exception:
        logger.exception("应用启动失败，开始回收资源")
        await _shutdown_scheduler()
        await _shutdown_redis()
        await _shutdown_db()
        raise


async def shutdown_event() -> None:
    logger.info(">>> shutdown")
    # await _shutdown_scheduler()
    await _shutdown_redis()
    await _shutdown_db()


@asynccontextmanager
async def lifespan(app: FastAPI):
    del app
    await startup_event()
    try:
        yield
    finally:
        await shutdown_event()
EOF
)"

write_file "$APP_DIR/core/middleware.py" "$(cat <<EOF
# -*- coding: utf-8 -*-
# @Time    : ${CURRENT_TIME}
# @Author  : ${AUTHOR}
# @File    : middleware.py

import json
import time
from typing import Iterable, Optional, Union

import shortuuid
from loguru import logger
from starlette.types import ASGIApp, Receive, Scope, Send


def _decode_headers(raw_headers) -> dict:
    return {k.decode().lower(): v.decode() for k, v in raw_headers}


def _mask_headers(headers: dict, sensitive_headers: set, mask: bool) -> dict:
    if not mask:
        return headers
    return {k: ("***" if k in sensitive_headers else v) for k, v in headers.items()}


def _parse_header_list(value: Union[str, Iterable[str], None]) -> set:
    if not value:
        return set()
    if isinstance(value, str):
        return {h.strip().lower() for h in value.split(",") if h.strip()}
    return {str(h).strip().lower() for h in value if str(h).strip()}


def _get_client_ip(headers: dict, client) -> str:
    xff = headers.get("x-forwarded-for")
    if xff:
        return xff.split(",")[0].strip()
    if client:
        return client[0]
    return "0.0.0.0"


class RequestLoggingMiddleware:
    def __init__(
            self,
            app: ASGIApp,
            *,
            log_headers: bool = False,
            log_body: bool = False,
            max_body_size: int = 1024 * 1024,
            exclude_paths: Optional[Iterable[str]] = None,
            sensitive_headers: Union[str, Iterable[str], None] = None,
            mask_sensitive_headers: bool = True,
    ):
        self.app = app
        self.log_headers = log_headers
        self.log_body = log_body
        self.max_body_size = max_body_size
        self.exclude_paths = set(exclude_paths or [])
        self.sensitive_headers = _parse_header_list(sensitive_headers)
        self.mask_sensitive_headers = mask_sensitive_headers

    def _is_excluded(self, path: str) -> bool:
        for p in self.exclude_paths:
            if p.endswith("*") and path.startswith(p[:-1]):
                return True
            if path == p:
                return True
        return False

    def _should_read_body(self, method: str, headers: dict) -> bool:
        if not self.log_body:
            return False
        if method in {"GET", "HEAD", "OPTIONS"}:
            return False
        content_type = headers.get("content-type", "").lower()
        if content_type.startswith("multipart/form-data"):
            return False
        try:
            content_length = int(headers.get("content-length", "0") or 0)
        except ValueError:
            return False
        if content_length <= 0 or content_length > self.max_body_size:
            return False
        return True

    async def _receive_body(self, receive: Receive) -> tuple[bytes, bool]:
        body = b""
        disconnected = False

        while True:
            message = await receive()
            msg_type = message.get("type")
            if msg_type == "http.request":
                body += message.get("body", b"")
                if not message.get("more_body", False):
                    break
                continue
            if msg_type == "http.disconnect":
                disconnected = True
                break
        return body, disconnected

    def _build_receive(self, body: bytes, original_receive: Receive, disconnected: bool) -> Receive:
        sent = False

        async def receive() -> dict:
            nonlocal sent
            if not sent:
                sent = True
                return {"type": "http.request", "body": body, "more_body": False}
            if disconnected:
                return {"type": "http.disconnect"}
            return await original_receive()

        return receive

    async def __call__(self, scope: Scope, receive: Receive, send: Send):
        if scope["type"] != "http":
            await self.app(scope, receive, send)
            return

        path = scope.get("path", "")
        if self._is_excluded(path):
            await self.app(scope, receive, send)
            return

        start = time.perf_counter()
        headers = _decode_headers(scope.get("headers", []))
        method = scope.get("method", "")
        query_string = scope.get("query_string", b"").decode()
        client = scope.get("client")
        request_id = headers.get("x-request-id") or headers.get("x-log-uuid") or shortuuid.uuid()
        scope.setdefault("state", {})["request_id"] = request_id

        body = b""
        if self._should_read_body(method, headers):
            body, disconnected = await self._receive_body(receive)
            receive = self._build_receive(body, receive, disconnected)

        status_code = None
        response_headers = []

        async def send_wrapper(message):
            nonlocal status_code, response_headers
            if message["type"] == "http.response.start":
                status_code = message.get("status")
                response_headers = list(message.get("headers", []))
                process_time = time.perf_counter() - start
                response_headers.append((b"x-process-time", f"{process_time:.6f}".encode()))
                if not any(k.lower() == b"x-request-id" for k, _ in response_headers):
                    response_headers.append((b"x-request-id", request_id.encode()))
                message["headers"] = response_headers
            await send(message)

        try:
            await self.app(scope, receive, send_wrapper)
        except Exception:
            logger.exception("请求处理异常")
            raise
        finally:
            elapsed_ms = (time.perf_counter() - start) * 1000
            full_path = f"{path}?{query_string}" if query_string else path
            ip = _get_client_ip(headers, client)
            logger.info(
                f"{method} {full_path} {status_code} {elapsed_ms:.2f}ms "
                f"ip={ip} rid={request_id}"
            )
            if self.log_headers:
                logger.info(
                    f"headers: {_mask_headers(headers, self.sensitive_headers, self.mask_sensitive_headers)}"
                )
            if self.log_body and body:
                content_type = headers.get("content-type", "").lower()
                body_text = body.decode("utf-8", errors="replace")
                if "application/json" in content_type:
                    try:
                        body_data = json.loads(body_text)
                    except Exception:
                        body_data = body_text
                else:
                    body_data = body_text
                logger.info(f"body: {body_data}")


MyMiddleware = RequestLoggingMiddleware
EOF
)"

write_file "$APP_DIR/core/pagination.py" "$(cat <<EOF
# -*- coding: utf-8 -*-
# @Time    : ${CURRENT_TIME}
# @Author  : ${AUTHOR}
# @File    : pagination.py

from typing import Dict, List

from pydantic import BaseModel
from sqlalchemy import and_, asc, desc, func, or_, select
from sqlalchemy.ext.asyncio import AsyncSession

from app.schemas.pagination import page_size, query_result
from app.utils.time_tools import TimeTools


class JsonFieldHandle:
    def __init__(self):
        pass


class CommonPaginateQuery:
    def __init__(
        self,
        request_data: BaseModel,
        orm_model,
        db_session: AsyncSession,
        model_pydantic: BaseModel = None,
        like_list: list = None,
        where_list: list = None,
        order_by_list: list = None,
        filter_range: dict = None,
        json_field_keys_to_obj: List[Dict] = None,
        json_field_obj_to_keys: List[Dict] = None,
        output_model: BaseModel = None,
        exclude_field: set = None,
        skip_list: List = None,
    ):
        self.request_data = request_data
        self.orm_model = orm_model
        self.db_session = db_session
        self.model_pydantic = model_pydantic
        self.like_list = like_list
        self.where_list = where_list
        self.order_by_list = order_by_list
        self.json_field_keys_to_obj = json_field_keys_to_obj
        self.json_field_obj_to_keys = json_field_obj_to_keys
        self.filter_range = filter_range
        self.output_model = output_model
        self.exclude_field = exclude_field or set()

        self.like_conditions = []
        self.where_conditions = []
        self.range_conditions = []
        self.records = []
        self.normal_data = []

        if skip_list:
            self.skip_list = skip_list + ["is_deleted"]
        else:
            self.skip_list = ["is_deleted"]

    @staticmethod
    def _parse_filter_key(key: str) -> tuple[str, str]:
        if "__" in key:
            field, op = key.split("__", 1)
            return field, op
        return key, "eq"

    def _build_expr(self, key: str, value):
        field, op = self._parse_filter_key(key)
        column = getattr(self.orm_model, field, None)
        if column is None:
            return None

        if op == "eq":
            return column == value
        if op == "icontains":
            return column.ilike(f"%{value}%")
        if op == "gte":
            return column >= value
        if op == "lte":
            return column <= value
        if op == "gt":
            return column > value
        if op == "lt":
            return column < value
        if op == "in":
            if not isinstance(value, (list, tuple, set)):
                value = [value]
            return column.in_(value)
        if op == "isnull":
            return column.is_(None) if bool(value) else column.is_not(None)
        return None

    async def build_filter_conditions(self):
        for k, v in self.request_data.model_dump().items():
            if v is None or (bool(v) is False and k not in self.skip_list):
                continue
            if k in self.like_list:
                self.like_conditions.append(getattr(self.orm_model, k).ilike(f"%{v}%"))
            if k in self.where_list:
                self.where_conditions.append(getattr(self.orm_model, k) == v)

    async def build_like(self):
        if not self.like_list:
            self.like_list = []

    async def build_where(self):
        if not self.where_list:
            self.where_list = []

    async def build_range(self):
        if not self.filter_range:
            return
        for k, v in self.filter_range.items():
            if v == "":
                continue
            expr = self._build_expr(k, v)
            if expr is not None:
                self.range_conditions.append(expr)

    async def build_order_by(self):
        if not self.order_by_list:
            self.order_by_list = []

    def _build_order_clauses(self):
        clauses = []
        for field in self.order_by_list:
            if field.startswith("-"):
                key = field[1:]
                column = getattr(self.orm_model, key, None)
                if column is not None:
                    clauses.append(desc(column))
            else:
                column = getattr(self.orm_model, field, None)
                if column is not None:
                    clauses.append(asc(column))
        return clauses

    async def _handle_json_field_keys_to_obj(self, model_data: dict):
        if not self.json_field_keys_to_obj:
            return
        for d in self.json_field_keys_to_obj:
            d_field = d.get("field")
            d_model = d.get("model")
            d_query_key = d.get("query_key")
            d_exclude_field = d.get("exclude_field") or set()
            value = model_data.get(d_field)
            if not (d_field and d_model and d_query_key and isinstance(value, list) and value):
                continue

            query_col = getattr(d_model, d_query_key, None)
            if query_col is None:
                continue
            stmt = select(d_model).where(query_col.in_(value))
            result = await self.db_session.execute(stmt)
            d_model_list = result.scalars().all()
            if not d_model_list:
                continue
            model_data[d_field] = [m.to_dict(exclude=d_exclude_field) for m in d_model_list]

    async def build_query(self):
        await self.build_like()
        await self.build_where()
        await self.build_filter_conditions()
        await self.build_range()
        await self.build_order_by()

        page = self.request_data.page
        now_page = page
        size = self.request_data.size
        offset, limit = page_size(page, size)

        where_clauses = []
        if self.where_conditions:
            where_clauses.extend(self.where_conditions)
        if self.like_conditions:
            where_clauses.append(or_(*self.like_conditions))
        if self.range_conditions:
            where_clauses.extend(self.range_conditions)

        count_stmt = select(func.count()).select_from(self.orm_model)
        if where_clauses:
            count_stmt = count_stmt.where(and_(*where_clauses))
        total_count = (await self.db_session.execute(count_stmt)).scalar_one()

        stmt = select(self.orm_model)
        if where_clauses:
            stmt = stmt.where(and_(*where_clauses))
        order_clauses = self._build_order_clauses()
        if order_clauses:
            stmt = stmt.order_by(*order_clauses)
        stmt = stmt.offset(offset).limit(limit)

        model_list = (await self.db_session.execute(stmt)).scalars().all()

        records = []
        for model in model_list:
            model_data = model.to_dict(exclude=self.exclude_field)
            if model_data.get("create_time"):
                model_data["create_time"] = TimeTools.convert_to_standard_format(model_data["create_time"])
            if model_data.get("update_time"):
                model_data["update_time"] = TimeTools.convert_to_standard_format(model_data["update_time"])
            if model_data.get("go_live_time"):
                model_data["go_live_time"] = TimeTools.convert_to_standard_format(model_data["go_live_time"])

            await self._handle_json_field_keys_to_obj(model_data)
            records.append(model_data)

        if self.output_model:
            records = [self.output_model.model_validate(model).model_dump() for model in records]

        self.records = records
        self.normal_data = query_result(records=self.records, now_page=now_page, total=total_count)
        return self.normal_data
EOF
)"

